preConditionHook:
// EEC E3 "Books Can Be Great", the book's composite kept WHOLE
// (deliberately NOT split): the shared shortma input drives BOTH the cross
// and the close filter, as the book has it -- splitting into
// MovingAverageCross + CloseAboveAverage would give each its own length.
// EL's Average recomputes from scratch every bar (EL_Summation_Probe), and
// EL Summation adds NEWEST-FIRST -- bar [0] first (the `bollingerband`
// register row). close is a price series with real history, so no warm-up
// mirroring is needed.
shortAvg = 0.0;
for (int i = 0; i < (int)shortma; ++i) {
    shortAvg += close[i];
}
shortAvg /= (int)shortma;
longAvg = 0.0;
for (int i = 0; i < (int)longma; ++i) {
    longAvg += close[i];
}
longAvg /= (int)longma;
// "crosses above/below" is a STATE MACHINE (EL_FEATURES.md `crosses` row,
// VERIFIED 2026-08-31), not a two-bar test: a cross fires on a bar whose
// toleranced relation is above/below AND whose most recent NON-equal relation
// was on the other side. An equality run (el_eq, absolute 2.22e-12) is
// bridged -- above -> equal -> above does NOT re-fire -- and the state starts
// UNKNOWN on the strategy's first evaluated bar, so nothing fires until a
// non-equal relation has been observed. The fire flags are computed BEFORE
// lastSide (0 unknown, +1 above, -1 below) is updated, and lastSide only
// moves on a non-equal bar.
crossUp = false;
crossDown = false;
if (el_gt(shortAvg, longAvg)) {
    crossUp = (lastSide == -1);
    lastSide = 1;
} else if (el_lt(shortAvg, longAvg)) {
    crossDown = (lastSide == 1);
    lastSide = -1;
}
// el_eq: equality run -- lastSide deliberately unchanged.
